/**
 * Automatically builds the authority funnel pages and assigns the front page.
 */
function closeclient_generate_pages() {
    closeclient_generate_cpt_data();

    $pages = array(
        'Home' => array('content' => '[closeclient_hero][closeclient_logo_ticker][closeclient_authority][closeclient_stats][closeclient_portfolio][closeclient_about][closeclient_services][closeclient_vsl][closeclient_process][closeclient_strategic_assets][closeclient_testimonials][closeclient_team][closeclient_products][closeclient_lead_magnet][closeclient_newsletter][closeclient_pricing][closeclient_faq][closeclient_booking_cta]', 'template' => ''),
        'Solutions' => array('content' => '[closeclient_hero][closeclient_services][closeclient_process][closeclient_pricing][closeclient_booking_cta]', 'template' => 'template-services.php', 'slug' => 'solutions'),
        'The Method' => array('content' => '[closeclient_about][closeclient_team][closeclient_authority][closeclient_booking_cta]', 'template' => 'template-about.php', 'slug' => 'the-method'),
        'Book Your Audit' => array('content' => '[closeclient_booking_cta][closeclient_faq]', 'template' => 'template-contact.php', 'slug' => 'book-audit'),
        'Strategic Insights' => array('content' => '', 'template' => 'index.php', 'slug' => 'strategic-insights'),
        'Success Proof' => array('content' => '', 'template' => 'template-portfolio.php', 'slug' => 'success-proof'),
        'Strategic Assets' => array('content' => '[closeclient_strategic_assets]', 'template' => '', 'slug' => 'strategic-assets'),
        'Success Blueprint' => array('content' => '[closeclient_lead_magnet]', 'template' => 'template-lead-magnet.php', 'slug' => 'blueprint'),
        'VSL Protocol' => array('content' => '[closeclient_vsl][closeclient_booking_cta]', 'template' => 'template-landing-page.php', 'slug' => 'vsl-protocol'),
        'Authority Protocol' => array('content' => '', 'template' => 'template-sales-page.php', 'slug' => 'protocol'),
        'Contact' => array('content' => '', 'template' => 'template-contact.php', 'slug' => 'contact'),
        'Privacy Policy' => array('content' => get_theme_mod('closeclient_privacy_content', 'Standard Privacy Policy text for CloseClient authorities.'), 'template' => '', 'slug' => 'privacy-policy'),
        'Terms of Service' => array('content' => get_theme_mod('closeclient_terms_content', 'Standard Terms of Service for CloseClient protocols.'), 'template' => '', 'slug' => 'terms-of-service'),
        'Thank You' => array('content' => '[closeclient_thank_you]', 'template' => 'template-thank-you.php', 'slug' => 'thank-you'),
    );

    foreach ( $pages as $title => $pdata ) {
        $check = get_page_by_title( $title );
        $args = array(
            'post_type'    => 'page',
            'post_title'   => $title,
            'post_content' => $pdata['content'],
            'post_status'  => 'publish'
        );
        if ( isset($pdata['slug']) ) {
            $args['post_name'] = $pdata['slug'];
        }

        if ( ! $check ) {
            $pid = wp_insert_post( $args );
        } else {
            $pid = $check->ID;
            $args['ID'] = $pid;
            wp_update_post( $args );
        }

        if ( ! empty($pdata['template']) ) {
            update_post_meta( $pid, '_wp_page_template', $pdata['template'] );
        }

        // Set Front Page
        if ( 'Home' === $title ) {
            update_option( 'show_on_front', 'page' );
            update_option( 'page_on_front', $pid );
        }

        // Set Posts Page
        if ( 'Strategic Insights' === $title ) {
            update_option( 'page_for_posts', $pid );
        }
    }

    closeclient_setup_menus();
}

/**
 * Automates menu creation and assignment.
 */
function closeclient_setup_menus() {
    $menu_name = 'Elite Authority Menu';
    $menu_exists = wp_get_nav_menu_object( $menu_name );

    if ( ! $menu_exists ) {
        $menu_id = wp_create_nav_menu( $menu_name );
        $pages = array('Home', 'Solutions', 'Success Proof', 'The Method', 'Strategic Insights', 'Book Your Audit');
        foreach ( $pages as $title ) {
            $page = get_page_by_title( $title );
            if ( $page ) {
                wp_update_nav_menu_item( $menu_id, 0, array(
                    'menu-item-title'     => $title,
                    'menu-item-object'    => 'page',
                    'menu-item-object-id' => $page->ID,
                    'menu-item-type'      => 'post_type',
                    'menu-item-status'    => 'publish'
                ) );
            }
        }

        $locations = get_theme_mod( 'nav_menu_locations' );
        $locations['menu-1'] = $menu_id;
        set_theme_mod( 'nav_menu_locations', $locations );
    }
}

/**
 * Utility Action Handler.
 */
function closeclient_handle_utilities() {
    if ( ! isset( $_GET['closeclient_action'] ) ) return;
    if ( ! current_user_can( 'manage_options' ) ) wp_die( 'Insufficient permissions.' );
    if ( ! isset( $_GET['_wpnonce'] ) || ! wp_verify_nonce( $_GET['_wpnonce'], 'closeclient_utility_action' ) ) wp_die( 'Security check failed.' );

    $action = sanitize_text_field( $_GET['closeclient_action'] );
    if ( 'reset' === $action ) {
        closeclient_reset_defaults();
        wp_redirect( admin_url( 'customize.php?closeclient_msg=reset_success' ) );
        exit;
    } elseif ( 'generate' === $action ) {
        closeclient_generate_pages();
        wp_redirect( admin_url( 'edit.php?post_type=page&closeclient_msg=gen_success' ) );
        exit;
    }
}
add_action( 'admin_init', 'closeclient_handle_utilities' );
